using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evaluation;

[TestClass]
public sealed class ChatEvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var chatClient = new ChatClientBuilder()
            .UseFunctionInvocation()
            .Use(new OllamaChatClient(new Uri("http://localhost:11434"), "llama3.2"));

        var chatConfiguration = new ChatConfiguration(chatClient);

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunDirectory!, "eval-results"),
            evaluators: GetEvaluators(),
            chatConfiguration: chatConfiguration);
    }

    private static IEnumerable<IEvaluator> GetEvaluators()
    {
        yield return new RelevanceEvaluator();
        yield return new CoherenceEvaluator();
        yield return new FluencyEvaluator();
    }

    [TestMethod]
    public async Task Chat_responds_relevantly_to_greeting()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_relevantly_to_greeting),
                iterationName: "default");

        IChatClient chatClient = run.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages, response);
    }

    [TestMethod]
    public async Task Chat_responds_relevantly_to_factual_question()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_relevantly_to_factual_question),
                iterationName: "default");

        IChatClient chatClient = run.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages, response);
    }

    [TestMethod]
    public async Task Chat_maintains_coherence_in_multiturn()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_maintains_coherence_in_multiturn),
                iterationName: "default");

        IChatClient chatClient = run.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
